{
  "gateway": "snapchat_native_action",
  "mode": "direct",
  "description": "Run a Snapchat Marketing API action by name for deferred or advanced operations. Prefer named tools such as create campaign, fetch ad account, upload media, and get insights when they are available.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "action": {
        "type": "string",
        "minLength": 1,
        "description": "Snapchat Marketing API action/tool name. Use LIST_ACTIONS with search/category pagination to discover names, or DESCRIBE_ACTION with target_action before a complex call. Friendly names such as snapchat_campaign_stats, snapchat_adsquad_stats, and snapchat_ad_stats are preferred; legacy *_stats_get names are accepted."
      },
      "target_action": {
        "type": "string",
        "description": "Action to inspect when action=DESCRIBE_ACTION."
      },
      "search": {
        "type": "string",
        "description": "Case-insensitive action/category/path filter when action=LIST_ACTIONS."
      },
      "category": {
        "type": "string",
        "description": "Optional category filter when action=LIST_ACTIONS."
      },
      "cursor": {
        "type": "integer",
        "minimum": 0,
        "description": "Zero-based catalog offset when action=LIST_ACTIONS."
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 100,
        "description": "Catalog page size when action=LIST_ACTIONS. Defaults to 25. For reporting actions, this remains the native Snapchat result limit."
      },
      "connection_id": {
        "type": "string",
        "format": "uuid",
        "description": "Optional Snapchat OAuth connection ID."
      },
      "ad_account_id": {
        "type": "string",
        "description": "Snapchat ad account ID."
      },
      "account_id": {
        "type": "string",
        "description": "Alias for ad_account_id."
      },
      "path_params": {
        "type": "object",
        "additionalProperties": {},
        "description": "Templated path params such as campaign_id or media_id."
      },
      "params": {
        "$ref": "#/properties/path_params",
        "description": "Native Snapchat params."
      },
      "query": {
        "$ref": "#/properties/path_params",
        "description": "Explicit query params."
      },
      "payload": {
        "description": "Native Snapchat body exactly as documented."
      },
      "aggregate_pages": {
        "type": "boolean",
        "default": false,
        "description": "Follow paging.next_link when true."
      },
      "max_pages": {
        "type": "integer",
        "minimum": 1,
        "maximum": 100,
        "default": 25,
        "description": "Page cap for aggregate_pages."
      },
      "confirmed": {
        "type": "boolean",
        "default": false,
        "description": "Required for destructive live calls."
      },
      "dry_run": {
        "type": "boolean",
        "default": true,
        "description": "Writes preview by default; read actions ignore it."
      },
      "skip_preflight": {
        "type": "boolean",
        "default": false,
        "description": "Bypass curated write/report preflight."
      },
      "idempotency_key": {
        "type": "string",
        "description": "Idempotency key for writes."
      },
      "result_fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Project MCP result records to these fields."
      },
      "fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Alias for result_fields unless the action has a native fields parameter."
      },
      "max_items": {
        "type": "integer",
        "minimum": 1,
        "maximum": 10000,
        "description": "Cap returned arrays in the MCP result."
      },
      "compact": {
        "type": "boolean",
        "default": false,
        "description": "Remove null, empty string, and empty object values from the MCP result."
      }
    },
    "required": [
      "action"
    ],
    "additionalProperties": true,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}
